from datetime import datetime,timezone
out=Path('research/readiness_2026_20261020/v1');m=json.loads(Path('research/workload_efficiency_model_batch_20261020/v1/MANIFEST.json').read_text());refs=dict(component=m['component_ref'],schedule=m['source_refs']['native_schedule'],ledger=m['accounting_ledger_ref'],scoreboard=json.loads(Path('research/scoreboard_result_features_20261020/v1/actual_receipt.json').read_text())['full_ref'])
