(out/'CACHE_2026_PROJECTION.json').write_text(json.dumps(record,indent=2,sort_keys=True)+'\n');print(dict(actors=len(actors),teams=len(teams),ledger=len(ledger),schedule=len(schedule),completed=len(completed),before_period=c['before_period'],seconds=record['elapsed_seconds']))
